<?php
namespace EventFlow\Tests\Integration;
use PHPUnit\Framework\TestCase;
final class Sprint10ImportAdministrationDeliveryTest extends TestCase
{public function testCompleteRoutesAndReadyModeCompositionAreExplicit():void{$routes=$this->source('src/Presentation/Api/ImportAdministrationRouteRegistrar.php');self::assertSame(4,substr_count($routes,'registerAuthenticatedGet'));self::assertSame(5,substr_count($routes,'registerAuthenticatedPost'));foreach(['/parse','/dry-run','/apply','/cancel','/rows','/result']as$route)self::assertStringContainsString($route,$routes);$mapping=$this->source('src/Presentation/Api/ImportRouteRegistrar.php');self::assertStringContainsString('registerAuthenticatedPut',$mapping);self::assertStringContainsString('/mapping',$mapping);$bootstrap=$this->source('src/Bootstrap/ApplicationBootstrap.php');self::assertStringContainsString('new HardenedImportUploadGuard()',$bootstrap);self::assertStringContainsString('$container->database->importAdministration',$bootstrap);self::assertStringContainsString('new ImportAdministrationRouteRegistrar(',$bootstrap);}public function testUploadBoundaryPreconditionsAndPrivacyControlsAreExplicit():void{$request=$this->source('src/Presentation/Api/RestRequest.php');self::assertStringContainsString('public function file',$request);$mapper=$this->source('src/Presentation/WordPress/WordPressRestRequestMapper.php');self::assertStringContainsString('get_file_params',$mapper);$guard=$this->source('src/Infrastructure/Import/HardenedImportUploadGuard.php');foreach(['isUploaded','MAX_BYTES','MIME','temporaryPath','move','delete']as$x)self::assertStringContainsString($x,$guard);self::assertStringNotContainsString("json()['path']",$this->source('src/Presentation/Api/ImportUploadController.php'));$admin=$this->source('src/Presentation/Api/ImportAdministrationController.php');self::assertSame(1,substr_count($admin,'MutationPreconditionPolicy::IF_MATCH_AND_IDEMPOTENCY_KEY'));self::assertStringContainsString('private function transition',$admin);$readme=$this->source('README-IMP-070.md');self::assertStringContainsString('JSON or query-supplied server paths are never accepted',$readme);}private function source(string$r):string{$contents=file_get_contents(dirname(__DIR__,2).'/'.$r);self::assertIsString($contents);return$contents;}}
